        shopify: ['Abre el elemento en el administrador de tu tienda (producto, página, entrada de blog o colección).', 'Baja hasta «Vista previa del listado en el motor de búsqueda» y pulsa el lápiz.', 'En «Meta descripción», escribe de 70 a 160 caracteres.', 'Pulsa Guardar.'],
        wix: ['En «Páginas y menú», pulsa los tres puntos junto a la página y luego «Conceptos básicos de SEO».', 'En «Meta descripción», escribe de 70 a 160 caracteres.', 'Publica la web.'],
        other: ['Abre la página en el sistema con el que está hecha tu web.', 'Busca un campo llamado «Meta descripción» o «Descripción para buscadores».', 'Escribe de 70 a 160 caracteres, distintos en cada página, y guarda.'],
