        shopify: ['Tienda online, Temas, Editar código, y abre robots.txt.liquid.', 'Borra los grupos que bloquean GPTBot, ClaudeBot, PerplexityBot y parecidos, y guarda.', 'Si no lo tienes claro, pregunta a quien desarrolló la plantilla.'],
