        shopify: ['Actualiza el enlace en la página donde aparece, o redirige la dirección antigua.', 'Para redirigir: Tienda online, Navegación, luego «Ver redireccionamientos de URL» y «Crear redireccionamiento de URL».', 'Escribe primero la dirección rota y después la página correcta, y pulsa Guardar.'],
