        shopify: ['Todas las plantillas oficiales de Shopify están preparadas para móvil. Esto suele venir de una edición del código de la plantilla.', 'Tienda online, Temas, Editar código, y en theme.liquid comprueba que hay una línea meta name="viewport".', 'Si no lo tienes claro, pregunta a quien desarrolló la plantilla.'],
