        shopify: ['Las plantillas oficiales de Shopify ponen una dirección canónica en cada página.', 'Si falta, la plantilla se ha editado: Tienda online, Temas, Editar código, y comprueba que theme.liquid tiene una línea link rel="canonical".', 'Si no lo tienes claro, contacta con quien desarrolló la plantilla.'],
        wix: ['Wix añade una dirección canónica a cada página.', 'En «Páginas y menú», los tres puntos junto a la página, «Conceptos básicos de SEO» y luego «SEO avanzado»: comprueba que «URL canónica» no apunta a otra página.', 'Publica la web.'],
        other: ['Añade una línea link rel="canonical" en la parte superior de la página con la dirección completa de la propia página.', 'Casi todos los creadores de webs tienen un campo para ello en los ajustes de SEO de la página. Guarda y publica.'],
