        wix: ['En «Páginas y menú», los tres puntos junto a la página, «Conceptos básicos de SEO» y luego «SEO avanzado».', 'En «Marcado de datos estructurados» añade un marcado que encaje con la página.', 'Publica y compruébalo con la «Prueba de resultados enriquecidos» de Google.'],
