        wordpress: ['Con el plugin de Go Top (versión 2.1.0 o posterior), pulsa «Arregladlo por mí» y construimos el texto a partir de tus páginas, tú lo revisas y el plugin lo sirve.', 'Sin el plugin: escribe un archivo de texto normal llamado llms.txt con el nombre de tu web, una línea sobre el negocio y tus páginas principales con una línea cada una.', 'Súbelo a la carpeta raíz de tu web, junto a robots.txt (con el gestor de archivos de tu alojamiento o por FTP), y abre tuweb/llms.txt para comprobarlo.'],
        shopify: ['Shopify no permite que las aplicaciones ni los comerciantes coloquen un archivo en la raíz de la dirección de la tienda, así que un llms.txt no se puede añadir automáticamente a una tienda de Shopify, ni por nuestra parte ni por la tuya.', 'Lo que sí ayuda a los asistentes de IA en Shopify: descripciones claras de productos y páginas, una página «Sobre nosotros» y preguntas frecuentes.', 'Si Shopify añade una forma de publicar llms.txt, lo añadiremos aquí.'],
        wix: ['Hoy Wix no permite subir un archivo a la raíz de la web, así que un llms.txt no se puede colocar en una web de Wix.', 'Mantén claras tu página «Sobre nosotros» y las descripciones de las páginas: eso es lo que leen los asistentes de IA.'],
        other: ['Escribe un archivo de texto normal llamado llms.txt: el nombre de tu web como encabezado con «# », una línea sobre el negocio y después tus páginas principales como una lista de enlaces con una línea cada una.', 'Súbelo a la carpeta raíz de tu web, junto a robots.txt.', 'Abre tuweb/llms.txt en el navegador para comprobar que aparece.'],
